// monster-models.js — manifest-driven monster models for synced tokens.
//
// public/assets/monsters/manifest.json (generated by
// tools/gen-monster-manifest.mjs, committed) maps every SRD monster index to a
// body plan, a normalized world height, a nameplate height and optional
// appearance variants — or, when tools/gltf-model-map.json maps it, to a
// vendored CC0 GLB (kind:'gltf', entry.url) instead. buildObjectFromData()
// hands token records to createMonsterTokenGroup(); monsters without a
// manifest entry (custom/homebrew tokens) keep the classic colored disc
// untouched.
//
// The manifest fetch is allowed to lose the race with 'map-state': the token is
// built as its disc inside the token group and swaps in the model the moment
// the manifest lands — position, selection and nameplate all survive because
// only the group's children change. GLB entries do the same swap, one fetch
// later: disc placeholder first, async model once the file loads (a failed
// load keeps the disc). In Node (no DOM) GLB entries return null and the
// caller's disc stands in, so tests never touch a loader.
//
// Model packs (lib/monster-packs.cjs, served under /packs/) arrive through the
// same manifest URL as extra kind:'gltf' entries. Those may declare `clips`
// (role → clip name), a shared clip-library GLB (`animUrl`, bound by bone
// name), bone `proportions` and a `breath` socket; such tokens get a live rig
// from monster-anim.js. Entries without `clips` stay posed and static.
//
// Seating contract: every model is scaled to the entry height and its soles
// are placed at TOKEN_SEAT_Y (-0.1), which is exactly the token halfHeight the
// pages already use for discs, so stored positions never migrate.

import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { clone as skeletonClone } from 'three/addons/utils/SkeletonUtils.js';
import { buildMonsterModel } from './monster-generators.js';
import { applyProportions, attachMonsterRig } from './monster-anim.js';
import { APE_APPEARANCE_VARIANTS, setMonsterVariantCatalog } from './monsters.js';

export const TOKEN_SEAT_Y = -0.1;
export const TOKEN_HALF_HEIGHT = 0.1;

const MANIFEST_URL = '/assets/monsters/manifest.json';

const HAS_DOM = typeof document !== 'undefined';

// Belt and braces: if the manifest never loads the textured ape pilot still
// renders exactly as before (height 1.1 → nameplate 1.52, variants intact).
const APE_FALLBACK_ENTRY = Object.freeze({
    index: 'ape',
    kind: 'procedural',
    plan: 'ape',
    height: 1.1,
    nameplateY: 1.52,
    variants: APE_APPEARANCE_VARIANTS,
    params: Object.freeze({})
});

let manifest = null;
let loadState = 'idle'; // 'idle' | 'loading' | 'ready' | 'failed'
let loadPromise = null;
const pending = [];

// --- manifest ----------------------------------------------------------------

function variantList(entry) {
    const variants = Array.isArray(entry && entry.variants) ? entry.variants : [];
    return variants
        .filter(variant => variant && typeof variant.id === 'string' && variant.id)
        .map(variant => Object.freeze({
            id: variant.id,
            label: String(variant.label || variant.id),
            description: String(variant.description || ''),
            ...(variant.params && typeof variant.params === 'object' ? { params: { ...variant.params } } : {})
        }));
}

function catalogFrom(entryMap) {
    const catalog = new Map();
    for (const [index, entry] of Object.entries(entryMap)) {
        const variants = variantList(entry);
        if (variants.length) catalog.set(index, variants);
    }
    return catalog;
}

// Validate, adopt and publish a manifest. Exported so tests (and the GM screen
// before any fetch) can feed it directly; loadMonsterModels() is the fetch path.
export function adoptMonsterManifest(json) {
    const monsters = json && json.monsters && typeof json.monsters === 'object' ? json.monsters : null;
    if (!monsters) throw new Error('monster manifest is missing its monsters map');
    manifest = {
        version: Number.isFinite(Number(json.version)) ? Number(json.version) : 1,
        monsters
    };
    loadState = 'ready';
    setMonsterVariantCatalog(catalogFrom(monsters));
    flushPending();
    return manifest;
}

export function loadMonsterModels() {
    if (loadPromise) return loadPromise;
    loadState = 'loading';
    loadPromise = fetch(MANIFEST_URL, { cache: 'no-cache' })
        .then(response => {
            if (!response.ok) throw new Error(`HTTP ${response.status}`);
            return response.json();
        })
        .then(json => adoptMonsterManifest(json))
        .catch(error => {
            loadState = 'failed';
            console.warn('[monsters] model manifest unavailable:', (error && error.message) || error);
            return null;
        });
    return loadPromise;
}

export function monsterManifest() {
    return manifest;
}

export function getMonsterEntry(index) {
    const key = String(index || '').toLowerCase();
    if (manifest && key) {
        const entry = manifest.monsters[key];
        return entry && typeof entry === 'object' ? entry : null;
    }
    return key === 'ape' ? APE_FALLBACK_ENTRY : null;
}

// Appearance options for a monster index: manifest variants, else the ape
// pilot's built-in set (see getMonsterEntry), else none.
export function monsterVariantOptions(index) {
    const entry = getMonsterEntry(index);
    return entry ? variantList(entry) : [];
}

function pickVariant(entry, requested) {
    const variants = variantList(entry);
    if (!variants.length) return null;
    const id = String(requested || '').trim().toLowerCase();
    return variants.find(variant => variant.id === id) || variants[0];
}

// --- building ----------------------------------------------------------------

function nameplateFor(entry) {
    const explicit = Number(entry && entry.nameplateY);
    if (Number.isFinite(explicit) && explicit >= 0.72 && explicit <= 20) return explicit;
    const height = Number(entry && entry.height);
    return Math.max(0.72, (Number.isFinite(height) ? height : 1) + 0.42);
}

function disposeChildren(group) {
    const seen = new Set();
    [...group.children].forEach(child => {
        // Presentation riding on the token (base plinth, nameplate, selection
        // ring) belongs to the token, not to the model being swapped out.
        const tag = child.userData || {};
        if (tag.tokenBase || tag.objectNameplate || tag.workspaceSelectionRing) return;
        child.traverse(object => {
            const onDispose = object.userData && object.userData.onDispose;
            if (typeof onDispose === 'function') {
                object.userData.onDispose = null;
                onDispose();
            }
            if (object.userData && object.userData.ownGeometry && object.geometry && !seen.has(object.geometry)) {
                seen.add(object.geometry);
                object.geometry.dispose();
            }
            const materials = Array.isArray(object.material) ? object.material : [object.material];
            materials.filter(Boolean).forEach(material => {
                if (seen.has(material)) return;
                seen.add(material);
                material.dispose();
            });
        });
        group.remove(child);
    });
}

// Build one manifest entry into a holder group: plan → measure → scale to the
// entry height → seat soles at TOKEN_SEAT_Y. Returns null when the plan fails
// (a bad manifest must degrade to the disc, never throw through map-state).
function seatInHolder(entry, model) {
    const bounds = new THREE.Box3().setFromObject(model);
    const natural = Math.max(1e-4, bounds.max.y - bounds.min.y);
    const target = Number(entry.height);
    const scale = Number.isFinite(target) && target > 0
        ? Math.max(0.05, Math.min(20, target / natural))
        : 1;
    model.scale.setScalar(scale);
    model.position.y = TOKEN_SEAT_Y - bounds.min.y * scale;

    const holder = new THREE.Group();
    holder.name = `MonsterModel:${entry.index}`;
    holder.add(model);
    return { holder, scale };
}

function buildTokenModel(entry, data) {
    const variant = pickVariant(entry, data && data.monsterVariant);
    const params = { ...(entry.params && typeof entry.params === 'object' ? entry.params : {}) };
    if (variant) {
        params.variant = variant.id;
        if (variant.params) Object.assign(params, variant.params);
    }
    let model;
    try {
        model = buildMonsterModel(entry.plan, params, { variant: variant && variant.id });
    } catch (error) {
        console.warn('[monsters] model build failed for', entry.index, error);
        return null;
    }
    if (!model) return null;
    return { ...seatInHolder(entry, model), variant };
}

function applyTokenMetadata(wrapper, built, entry) {
    wrapper.userData.halfHeight = TOKEN_HALF_HEIGHT;
    wrapper.userData.nameplateY = nameplateFor(entry);
    wrapper.userData.monsterIndex = entry.index;
    wrapper.userData.monsterPlan = entry.plan;
    wrapper.userData.monsterHeight = Number(entry.height) || null;
    if (built.variant) wrapper.userData.monsterVariant = built.variant.id;
    wrapper.userData.monsterScale = built.scale;
    // disposeBuiltObject only runs the top-level callback; forward it so the
    // ape can flag itself disposed (cancelling pending texture work).
    wrapper.userData.disposed = false;
    wrapper.userData.onDispose = () => {
        wrapper.userData.disposed = true;
        wrapper.traverse(child => {
            if (child === wrapper) return;
            const onDispose = child.userData && child.userData.onDispose;
            if (typeof onDispose === 'function') {
                child.userData.onDispose = null;
                onDispose();
            }
        });
    };
    // A nameplate may already exist (disc phase); re-seat it for the model.
    const plate = wrapper.userData.objectNameplate;
    if (plate) plate.position.y = wrapper.userData.nameplateY;
}

function swapInModel(wrapper, entry, data) {
    if (wrapper.userData.disposed) return;
    const built = buildTokenModel(entry, data);
    if (!built) return;
    disposeChildren(wrapper);
    wrapper.add(built.holder);
    applyTokenMetadata(wrapper, built, entry);
}

// --- vendored GLBs (kind: 'gltf') -------------------------------------------

let gltfLoader = null;
const glbTemplates = new Map(); // url -> Promise<GLTF>

// Load one GLB once per session and pose its first animation frame on the
// template, so every token clone starts posed (not in bind pose). Failed
// loads evict the promise so a later token can retry.
function loadGlbTemplate(url) {
    if (!glbTemplates.has(url)) {
        const promise = new Promise((resolve, reject) => {
            const loader = gltfLoader || (gltfLoader = new GLTFLoader());
            loader.load(url, gltf => {
                const clip = gltf && gltf.animations && gltf.animations[0];
                if (clip && gltf.scene) {
                    const mixer = new THREE.AnimationMixer(gltf.scene);
                    mixer.clipAction(clip).play();
                    mixer.update(0);
                    mixer.stopAllAction();
                    mixer.uncacheRoot(gltf.scene);
                }
                resolve(gltf);
            }, undefined, reject);
        });
        promise.catch(() => glbTemplates.delete(url));
        glbTemplates.set(url, promise);
    }
    return glbTemplates.get(url);
}

// The tabletop renderers output linear (no gamma), and every colour in the
// game is authored for that. A pack model's sRGB base-colour texture would be
// decoded and then shown undecoded — far too dark — so its colour maps are
// read as-is instead. Done once per template; revisit if the tabletop ever
// switches to sRGB output.
const colourFixed = new WeakSet();
function showPackColoursAsAuthored(gltf) {
    if (!gltf || !gltf.scene || colourFixed.has(gltf)) return;
    colourFixed.add(gltf);
    gltf.scene.traverse(object => {
        const materials = Array.isArray(object.material) ? object.material : [object.material];
        for (const material of materials.filter(Boolean)) {
            for (const texture of [material.map, material.emissiveMap].filter(Boolean)) {
                if ('colorSpace' in texture) texture.colorSpace = THREE.NoColorSpace || '';
                else if (THREE.LinearEncoding != null) texture.encoding = THREE.LinearEncoding;
                texture.needsUpdate = true;
            }
            material.needsUpdate = true;
        }
    });
}

// A pack entry's `tint` multiplies the base colour (age stages of one sculpt).
// Tinted materials are cloned once per (model, tint) and shared by its tokens.
const tintedMaterials = new Map(); // `${url}|${tint}` → Map<material, clone>
function applyTint(model, entry) {
    if (typeof entry.tint !== 'string' || !entry.tint) return;
    const key = `${entry.url}|${entry.tint}`;
    if (!tintedMaterials.has(key)) tintedMaterials.set(key, new Map());
    const clones = tintedMaterials.get(key);
    const tint = new THREE.Color(entry.tint);
    const swap = material => {
        if (!material || !material.color) return material;
        if (!clones.has(material)) {
            const clone = material.clone();
            clone.color.multiply(tint);
            clones.set(material, clone);
        }
        return clones.get(material);
    };
    model.traverse(object => {
        if (!object.material) return;
        object.material = Array.isArray(object.material) ? object.material.map(swap) : swap(object.material);
    });
}

// Clone the shared template, then the usual measure → scale → seat path.
// GLB entries carry no variants; a missing URL degrades to the disc.
async function buildGltfTokenModel(entry) {
    if (!HAS_DOM || typeof entry.url !== 'string' || !entry.url) return null;
    const gltf = await loadGlbTemplate(entry.url);
    if (!gltf || !gltf.scene) return null;
    if (entry.pack) showPackColoursAsAuthored(gltf);
    const model = skeletonClone(gltf.scene);
    applyProportions(model, entry.proportions);
    applyTint(model, entry);
    let clips = null;
    if (entry.clips) {
        // A missing clip library only costs the clips it carried.
        const library = typeof entry.animUrl === 'string' && entry.animUrl
            ? await loadGlbTemplate(entry.animUrl).catch(() => null)
            : null;
        clips = [...(gltf.animations || []), ...((library && library.animations) || [])];
    }
    return { ...seatInHolder(entry, model), variant: null, model, clips };
}

// Async counterpart of swapInModel: disc placeholder first, model the moment
// the file lands. Any failure (network, parse, disposed token) keeps the disc.
function swapInGltf(wrapper, entry) {
    if (!HAS_DOM || wrapper.userData.disposed) return;
    buildGltfTokenModel(entry)
        .then(built => {
            if (!built || wrapper.userData.disposed) return;
            disposeChildren(wrapper);
            wrapper.add(built.holder);
            applyTokenMetadata(wrapper, built, entry);
            if (built.clips) attachMonsterRig(wrapper, built.holder, built.model, entry, built.clips);
        })
        .catch(error => console.warn('[monsters] GLB load failed for', entry.index, error));
}

function flushPending() {
    const queued = pending.splice(0, pending.length);
    for (const item of queued) {
        const entry = manifest && manifest.monsters[item.index];
        if (!entry) continue; // No entry: the disc placeholder stays — same visuals as always.
        if (entry.kind === 'gltf') swapInGltf(item.wrapper, entry);
        else swapInModel(item.wrapper, entry, item.data);
    }
}

// Build the model group for a synced token record, or return null when the
// caller should keep its plain disc (custom tokens, GLB slots, failed builds).
// `makeDisc` is only called when a placeholder is actually needed.
export function createMonsterTokenGroup(data, makeDisc) {
    const index = String(data && data.monsterData && data.monsterData.index || '').toLowerCase();
    if (!index) return null;

    if (loadState === 'ready') {
        const entry = manifest.monsters[index];
        if (!entry) return null;
        if (entry.kind === 'gltf') {
            if (!HAS_DOM) return null;
            const wrapper = new THREE.Group();
            wrapper.add(makeDisc());
            applyTokenMetadata(wrapper, { variant: null, scale: null }, entry);
            swapInGltf(wrapper, entry);
            return wrapper;
        }
        const wrapper = new THREE.Group();
        const built = buildTokenModel(entry, data);
        if (!built) return null;
        wrapper.add(built.holder);
        applyTokenMetadata(wrapper, built, entry);
        return wrapper;
    }

    if (loadState === 'loading') {
        const wrapper = new THREE.Group();
        wrapper.userData.disposed = false;
        wrapper.add(makeDisc());
        pending.push({ wrapper, data, index });
        return wrapper;
    }

    // 'idle' / 'failed': the manifest may never arrive, so only the ape pilot
    // (known locally) gets its model; everything else keeps the disc.
    const entry = index === 'ape' ? APE_FALLBACK_ENTRY : null;
    if (!entry) return null;
    const wrapper = new THREE.Group();
    const built = buildTokenModel(entry, data);
    if (!built) return null;
    wrapper.add(built.holder);
    applyTokenMetadata(wrapper, built, entry);
    return wrapper;
}
